def find_abc(limit):
    results = []
    for a in range(1, limit):
        for b in range(1, a):
            for c in range(1, b):
                s = a + b + c
                q = a*b + b*c + c*a
                p = a*b*c
                if (s * q) % p == 0:
                    results.append((a, b, c))
                    if len(results) > 100:
                        return results
    return results

print(find_abc(50))

