def count_solutions(limit):
    count = 0
    for a in range(1, limit):
        for b in range(1, a):
            for c in range(1, b):
                s = a + b + c
                q = a*b + b*c + c*a
                p = a*b*c
                if (s * q) % p == 0:
                    count += 1
    return count

for i in range(1, 101, 10):
    print(f"{i}: {count_solutions(i)}")

