            if delta >= 0:
                sqrt_delta = int(math.isqrt(delta))
                if sqrt_delta * sqrt_delta == delta:
                    for s_val in [(-b + sqrt_delta) // (2*a), (-b - sqrt_delta) // (2*a)]:
                        if s_val > k:
                            l_val = s_val - k
                            if l_val > 0 and l_val < k:
                                print(f"k={k}, l={l_val}, m={m}")

